#!/usr/bin/env bash
set -euo pipefail

BASE_BRANCH="codex/koswork-computer-control-20261029"
REQUIRED_BASE_COMMIT="7d6be59bec41deda0bbb695be4266d9317178229"
TARGET_BRANCH="${1:-feature/koswork-workspace-folder-20261029}"

echo "[1/6] Fetching origin/$BASE_BRANCH..."
git fetch origin "$BASE_BRANCH"

if ! git cat-file -e "$REQUIRED_BASE_COMMIT^{commit}" 2>/dev/null; then
  echo "ERROR: Base commit $REQUIRED_BASE_COMMIT not found after fetching $BASE_BRANCH" >&2
  exit 1
fi

echo "[2/6] Creating branch $TARGET_BRANCH from $REQUIRED_BASE_COMMIT..."
git checkout -B "$TARGET_BRANCH" "$REQUIRED_BASE_COMMIT"

echo "[3/6] Extracting Koswork Workspace Folder module..."
python3 - <<'INNER_PY'
import base64, io, tarfile
payload = base64.b64decode('''''')
with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as tf:
    tf.extractall(".")
INNER_PY

echo "[4/6] Running local temporary-folder demo and tests..."
node desktop/windows/workspace/demo.cjs
node --test desktop/windows/test/koswork-workspace.test.cjs
npm --prefix desktop/windows run check

echo "[5/6] Committing changes on $TARGET_BRANCH..."
git add desktop/windows/workspace desktop/windows/test/koswork-workspace.test.cjs docs/handoff/KOSWORK_WORKSPACE_FOLDER.md
git commit -m "feat(koswork): implement bounded owner workspace folder module with version checks and backups"

echo "[6/6] Pushing branch and opening Draft PR against $BASE_BRANCH..."
git push -u origin "$TARGET_BRANCH"
if command -v gh >/dev/null 2>&1; then
  gh pr create --draft \
    --base "$BASE_BRANCH" \
    --head "$TARGET_BRANCH" \
    --title "feat(koswork): Рабочая папка Koswork (desktop/windows/workspace)" \
    --body-file docs/handoff/KOSWORK_WORKSPACE_FOLDER.md
else
  echo "gh CLI not installed; open Draft PR from $TARGET_BRANCH into $BASE_BRANCH on GitHub."
fi
